body.script:
 let currentTxnId = ""; // Start Transaction on Load async
			function init() { try { const res = await fetch('/api/cart/begin', {
			method: 'POST' }); if (!res.ok) throw new Error("Failed to start
			transaction"); const data = await res.json(); currentTxnId =
			data.transactionId; document.getElementById('txn-display').innerText
			= `Txn: ${currentTxnId}`; } catch (err) {
			console.error("Initialization Error:", err); alert("Could not
			connect to the POS server. Check if port 8081 is active."); } }
			async function addItem() { const skuInput =
			document.getElementById('sku-input'); const sku = skuInput.value; if
			(!sku) { alert("Please enter a SKU"); return; } try { const res =
			await fetch(`/api/cart/${currentTxnId}/add`, { method: 'POST',
			headers: { 'Content-Type': 'application/json' }, body:
			JSON.stringify({ itemId: sku, quantity: 1 }) }); const txn = await
			res.json(); updateUI(txn); skuInput.value = ""; // Clear input after
			adding } catch (err) { console.error("Add Item Error:", err); } }
			async function processPayment() { try { const res = await
			fetch(`/api/cart/${currentTxnId}/pay`, { method: 'POST' }); const
			blob = await res.blob(); const url =
			window.URL.createObjectURL(blob); const a =
			document.createElement('a'); a.href = url; a.download =
			`Receipt_${currentTxnId}.pdf`; document.body.appendChild(a);
			a.click(); a.remove(); alert("Transaction Completed and XML Stored!");
			location.reload(); } catch (err) { console.error("Payment Error:",
			err); } } function updateUI(txn) { const table =
			document.getElementById('cart-table'); if (!txn.items) return;
			table.innerHTML = txn.items.map(i => ` 

				${i.description}
				${i.quantity}
				$${i.price.toFixed(2)}

			`).join(''); document.getElementById('total-amount').innerText =
			`$${txn.totalAmount.toFixed(2)}`; } // Call init when the page loads
			init();
